"""
agent.py
Agentic AI core — orchestrates user profiling, prompt construction,
guardrails, and nutrition plan generation using IBM Granite /
meta-llama/llama-3-3-70b-instruct on watsonx.ai.
"""

from __future__ import annotations
import re
from granite_client import generate_text

# ---------------------------------------------------------------------------
# Medical disclaimer (always appended)
# ---------------------------------------------------------------------------
MEDICAL_DISCLAIMER = (
    "\n\n---\n"
    "⚕️ **MEDICAL DISCLAIMER:** This nutrition plan is generated by an AI "
    "assistant for informational purposes only. It is NOT a substitute for "
    "professional medical or dietary advice. Always consult a qualified "
    "healthcare provider or registered dietitian before making changes to "
    "your diet, especially if you have a medical condition such as diabetes, "
    "hypertension, or any other health concern. Do not ignore professional "
    "medical advice based on information provided by this application."
)

# ---------------------------------------------------------------------------
# Guardrail keywords — block harmful / off-topic requests
# ---------------------------------------------------------------------------
_BLOCKED_PATTERNS = [
    r"\b(suicide|self[- ]harm|overdose|poison|drug abuse|illegal)\b",
    r"\b(bomb|weapon|hack|exploit)\b",
    r"ignore (previous|above|all) instructions",
    r"(disregard|forget) (your|the) (guidelines|rules|restrictions)",
    r"jailbreak",
]
_COMPILED_BLOCKS = [re.compile(p, re.IGNORECASE) for p in _BLOCKED_PATTERNS]


def _is_safe(text: str) -> bool:
    """Return False if the input triggers any guardrail pattern."""
    for pattern in _COMPILED_BLOCKS:
        if pattern.search(text):
            return False
    return True


# ---------------------------------------------------------------------------
# Prompt builders
# ---------------------------------------------------------------------------

# ---------------------------------------------------------------------------
# System persona (shared)
# ---------------------------------------------------------------------------
_SYSTEM_PERSONA = (
    "You are NutriGuide, a helpful, respectful, and ethical AI nutrition assistant "
    "powered by IBM watsonx.ai. You provide evidence-based, culturally sensitive, and "
    "personalised nutrition advice. You NEVER recommend dangerous diets, extreme "
    "calorie restriction below 1200 kcal/day, or unproven supplements. "
    "You always use inclusive, non-judgmental language and a warm, encouraging tone. "
    "You follow Helpful, Accurate, and Mindful (HAM) principles. "
    "For any medical condition, you provide safe general guidance and always remind "
    "the user to consult a qualified healthcare professional."
)


def _build_nutrition_prompt(user: dict) -> tuple[str, str]:
    """
    Return (system_prompt, user_prompt) for the nutrition plan request.
    Uses Llama 3 chat format via the system/user message split.
    """
    name      = user.get("name", "User")
    age       = user.get("age", "unknown")
    diet_pref = user.get("diet_preference", "vegetarian")
    medical   = user.get("medical_history", "none")
    city      = user.get("city", "")
    country   = user.get("country", "")
    location  = f"{city}, {country}".strip(", ") or "unspecified"
    goal      = user.get("goal", "maintain a healthy lifestyle")
    activity  = user.get("activity_level", "moderately active")

    user_prompt = (
        f"Please create a detailed 7-day personalised nutrition plan for the following person:\n\n"
        f"- Name: {name}\n"
        f"- Age: {age}\n"
        f"- Diet Preference: {diet_pref}\n"
        f"- Medical History: {medical}\n"
        f"- Location: {location}\n"
        f"- Goal: {goal}\n"
        f"- Activity Level: {activity}\n\n"
        "The plan must include:\n"
        "1. A brief nutritional assessment based on the user's profile.\n"
        "2. Daily calorie and macro targets (proteins, carbs, fats).\n"
        "3. A 7-day meal plan (breakfast, lunch, dinner, and 2 snacks per day) "
        "using locally available, affordable foods suited to the user's location and diet preference.\n"
        "4. Specific guidance for any medical conditions mentioned.\n"
        "5. Hydration recommendations.\n"
        "6. Foods to avoid given the medical history.\n"
        "7. Practical tips to maintain the plan.\n\n"
        "Format clearly with headers and bullet points."
    )

    return _SYSTEM_PERSONA, user_prompt


def _build_query_prompt(question: str, user_context: dict | None = None) -> tuple[str, str]:
    """Return (system_prompt, user_prompt) for a general nutrition query."""
    context_block = ""
    if user_context:
        context_block = (
            f"User context — Name: {user_context.get('name', '')}, "
            f"Age: {user_context.get('age', '')}, "
            f"Diet: {user_context.get('diet_preference', '')}, "
            f"Medical history: {user_context.get('medical_history', 'none')}.\n\n"
        )

    system_prompt = (
        _SYSTEM_PERSONA
        + " Answer only nutrition, diet, and wellness-related questions. "
        "Refuse off-topic or harmful requests politely. "
        "Remind the user that your advice is general and not a medical diagnosis."
    )

    user_prompt = f"{context_block}User question: {question}"
    return system_prompt, user_prompt


# ---------------------------------------------------------------------------
# Public agent functions
# ---------------------------------------------------------------------------

def generate_nutrition_plan(user: dict) -> dict:
    """
    Validate user data, apply guardrails, call Granite, and return the plan.

    Returns:
        {"success": True,  "plan": str}  or
        {"success": False, "error": str}
    """
    # Basic validation
    required = ["name", "age", "diet_preference"]
    for field in required:
        if not user.get(field):
            return {"success": False, "error": f"Missing required field: {field}"}

    # Age sanity check
    try:
        age = int(user["age"])
        if not (1 <= age <= 120):
            raise ValueError
    except ValueError:
        return {"success": False, "error": "Please provide a valid age (1–120)."}

    # Guardrail on free-text fields
    combined_text = " ".join([
        str(user.get("medical_history", "")),
        str(user.get("goal", "")),
        str(user.get("name", "")),
    ])
    if not _is_safe(combined_text):
        return {
            "success": False,
            "error": (
                "Your request contains content that cannot be processed. "
                "Please ensure your inputs are related to nutrition and health."
            ),
        }

    try:
        system_prompt, user_prompt = _build_nutrition_prompt(user)
        raw_plan = generate_text(user_prompt, system_prompt)
        plan_with_disclaimer = raw_plan + MEDICAL_DISCLAIMER
        return {"success": True, "plan": plan_with_disclaimer}
    except RuntimeError as exc:
        return {"success": False, "error": str(exc)}


def answer_query(question: str, user_context: dict | None = None) -> dict:
    """
    Resolve a user's common nutrition/health query.

    Returns:
        {"success": True,  "answer": str}  or
        {"success": False, "error": str}
    """
    if not question or not question.strip():
        return {"success": False, "error": "Please enter a question."}

    if not _is_safe(question):
        return {
            "success": False,
            "error": (
                "Your question contains content that cannot be processed. "
                "Please ask a nutrition or health-related question."
            ),
        }

    try:
        system_prompt, user_prompt = _build_query_prompt(question.strip(), user_context)
        raw_answer = generate_text(user_prompt, system_prompt)
        answer_with_disclaimer = raw_answer + MEDICAL_DISCLAIMER
        return {"success": True, "answer": answer_with_disclaimer}
    except RuntimeError as exc:
        return {"success": False, "error": str(exc)}
